<?php require __DIR__.'/../config/config.php'; require_login(['student','parent']);$pdo=db();$sid=(int)(user()['student_id']??0);$student=null;if($sid){$s=$pdo->prepare('SELECT s.*,c.class_name,c.section FROM students s LEFT JOIN classes c ON c.id=s.class_id WHERE s.id=?');$s->execute([$sid]);$student=$s->fetch();}$notices=$pdo->query("SELECT * FROM notices WHERE active=1 AND audience IN ('all','students','parents') ORDER BY id DESC LIMIT 8")->fetchAll();$hw=[];$results=[];$fees=[];$attendance=[];if($student){$s=$pdo->prepare('SELECT h.*,sub.subject_name,c.class_name,c.section FROM homework h JOIN subjects sub ON sub.id=h.subject_id JOIN classes c ON c.id=h.class_id WHERE h.class_id=? ORDER BY h.due_date DESC LIMIT 10');$s->execute([$student['class_id']]);$hw=$s->fetchAll();$s=$pdo->prepare('SELECT r.*,e.exam_name,sub.subject_name FROM results r JOIN exams e ON e.id=r.exam_id JOIN subjects sub ON sub.id=r.subject_id WHERE r.student_id=? ORDER BY r.id DESC LIMIT 30');$s->execute([$sid]);$results=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM fees WHERE student_id=? ORDER BY id DESC LIMIT 12');$s->execute([$sid]);$fees=$s->fetchAll();$s=$pdo->prepare("SELECT status,COUNT(*) n FROM attendance WHERE student_id=? GROUP BY status");$s->execute([$sid]);$attendance=$s->fetchAll();} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Portal | Beacon</title><link rel="stylesheet" href="../assets/css/app.css"></head><body class="portal"><header class="portal-head"><a href="../index.html" class="brand"><img src="../assets/images/school-logo.jpeg"><div><strong>The New Beacon</strong><small>STUDENT PORTAL · LARKANA</small></div></a><div><span><?=e(user()['full_name'])?></span> · <a href="logout.php">Logout</a></div></header><main class="portal-main"><section class="welcome-banner"><div><span class="kicker">WELCOME BACK</span><h1><?=e($student['student_name']??user()['full_name'])?></h1><p><?=e(($student['class_name']??'Portal'). ' '.($student['section']??''))?></p></div><div class="portal-avatar">🎓</div></section><?php if(!$student):?><div class="alert warning">Your account is active, but it is not linked to a student record yet. An administrator must set the student_id for this user.</div><?php endif;?><div class="portal-grid"><section class="panel"><h2>Attendance</h2><?php $att=[];foreach($attendance as $a)$att[$a['status']]=(int)$a['n'];$tot=array_sum($att);$pr=$tot?round(($att['present']??0)/$tot*100):0;?><div class="big-number"><?=$pr?>%<small>Attendance rate</small></div><p>Present: <?=$att['present']??0?> · Absent: <?=$att['absent']??0?> · Leave: <?=$att['leave']??0?></p></section><section class="panel"><h2>Fee Balance</h2><?php $balance=0;foreach($fees as $f)$balance+=(float)$f['amount']-(float)$f['paid_amount'];?><div class="big-number">Rs <?=number_format($balance,2)?><small>Outstanding</small></div></section></div><div class="grid2"><section class="panel"><h2>Latest Results</h2><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Subject</th><th>Marks</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r['exam_name'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['marks'].' / '.$r['total_marks'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Homework</h2><?php foreach($hw as $h):?><article class="notice"><b><?=e($h['title'])?></b><small><?=e($h['subject_name'])?> · Due <?=e($h['due_date']?:'—')?></small><p><?=e($h['description'])?></p></article><?php endforeach;?></section></div><section class="panel"><h2>School Notices</h2><?php foreach($notices as $n):?><article class="notice"><span class="badge"><?=e($n['audience'])?></span><h3><?=e($n['title'])?></h3><p><?=nl2br(e($n['body']))?></p></article><?php endforeach;?></section></main></body></html>
